import{z as B,x as i,o as e,c as n,q as r,j as s,D as E,d as A,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"虚拟机逃逸","description":"","frontmatter":{"title":"虚拟机逃逸","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vm-escape.md","filePath":"cs/vm-escape.md","lastUpdated":1791413859000}'),p={name:"cs/vm-escape.md"};function d(h,a,_,c,m,T){const t=i("Mermaid");return e(),n("div",null,[a[2]||(a[2]=r('<h1 id="虚拟机逃逸" tabindex="-1">虚拟机逃逸 <a class="header-anchor" href="#虚拟机逃逸" aria-label="Permalink to &quot;虚拟机逃逸&quot;">​</a></h1><div class="epigraph"><p>虚拟机把客当做不可信，但设备模拟、共享内存与管理接口是 TCB。逃逸指客中代码到达宿主机。防御是缩小模拟面、设备 IOMMU、及时补丁，而不是假设「有虚拟化即隔离」。</p><footer>—— 据 Barham et al., Xen, SOSP 2003 的隔离目标；对照 Anderson；CVE 史仅作动机点名</footer></div><p>上一课<a href="/cs/flush-reload">Flush+Reload</a>还是共驻下的机密性泄漏；缺口是<strong>完整性边界</strong>：客中代码能否到达宿主机。本课讲虚拟化的 TCB 面，不给逃逸 PoC。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>现代虚拟化把 CPU 与内存的拦截交给硬件，但设备仍靠宿侧的模拟代码：QEMU 的设备模型、virtio 后端、管理 API 都在特权侧解析客机发来的数据——模拟代码里的洞就是宿里的洞。缺口是三件收缩：最小设备模型（不给客机用不到的设备）、快照加及时补丁（逃逸漏洞的暴露窗口以天计）、生产上关闭嵌套虚拟化等非必要特性。</p><p><span class="marginnote">直觉类比：设备模型像替客人收发包裹的前台——客人递来什么单子它都得拆开看（解析不可信数据），前台自己的漏洞就是整栋楼（宿主）的漏洞；把客人用不到的前台撤掉（最小设备集），是最便宜也最有效的一笔安全支出。</span></p>',7)),(e(),s(o,null,{default:E(()=>[l(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20GUEST%5B%22%E5%AE%A2%E6%9C%BA%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20DEVM%5B%22%E8%AE%BE%E5%A4%87%E6%A8%A1%E6%8B%9F%E5%B1%82%22%5D%0A%20%20GUEST%20--%3E%20BACK%5B%22virtio%20%E5%90%8E%E7%AB%AF%22%5D%0A%20%20GUEST%20--%3E%20MGMT%5B%22%E7%AE%A1%E7%90%86%20API%22%5D%0A%20%20DEVM%20--%3E%20HOLE%5B%22%E7%89%B9%E6%9D%83%E4%BE%A7%E8%A7%A3%E6%9E%90%E4%B8%8D%E5%8F%AF%E4%BF%A1%E6%95%B0%E6%8D%AE%E7%9A%84%E4%BB%A3%E7%A0%81%22%5D%0A%20%20BACK%20--%3E%20HOLE%0A%20%20MGMT%20--%3E%20HOLE%0A%20%20HOLE%20--%3E%20HOST%5B%22%E5%AE%BF%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20SHRINK%5B%22%E6%94%B6%E7%BC%A9%3A%20%E6%9C%80%E5%B0%8F%E8%AE%BE%E5%A4%87%E9%9B%86%20%2F%20%E5%8F%8A%E6%97%B6%E8%A1%A5%E4%B8%81%20%2F%20%E5%85%B3%E9%97%AD%E5%B5%8C%E5%A5%97%22%5D%20--%3E%20SURF%5B%22%E6%94%BB%E5%87%BB%E9%9D%A2%E6%94%B6%E7%AA%84%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h3 id="机密计算" tabindex="-1">机密计算 <a class="header-anchor" href="#机密计算" aria-label="Permalink to &quot;机密计算&quot;">​</a></h3><p>机密计算（TEE 型虚机）防的是运营商窥视内存；它不自动防一个客机逃逸去打另一个客机——那要另配宿内网络与工作负载策略，别把两个威胁混为一谈。</p><p><span class="marginnote">Xen/KVM 文献。禁止逃逸教程。容器下一课是更薄的边界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把 IaaS 威胁模型写清楚：谁是对手（同宿租户、被攻陷的客机、云内部人员）、信任谁（hypervisor 加设备模拟）、每类洞由谁修。补丁窗口要量化：高危逃逸 CVE 从披露到全舰队打齐的天数就是风险敞口。下一课容器逃逸。</p><p><span class="marginnote">数字实例：高危逃逸漏洞从披露到全舰队打齐补丁若需 7 天，这 7 天就是明码标价的风险敞口——把「窗口以天计」写进威胁模型，意味着多租户平台这期间的调度与隔离决策都得自己顶住，不能指望别人先修好。</span></p>',6)),(e(),s(o,null,{default:E(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20GUEST%5B%22%E5%AE%A2%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%E6%A8%A1%E6%8B%9F%20TCB%22%5D%0A%20%20DEV%20--%3E%20HOST%5B%22%E5%AE%BF%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20MIN%5B%22%E7%BC%A9%E5%B0%8F%E6%A8%A1%E6%8B%9F%E9%9D%A2%22%5D%20--%3E%20HARD%5B%22%E6%8F%90%E9%AB%98%E9%80%83%E9%80%B8%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制一句话：隔离强度等于 TCB 的正确性。hypervisor 的代码量比通用内核小一个量级、攻击面小，但设备模拟把它重新拉大——削减模拟面因此直接兑换安全。容器共用宿内核，syscall 界面巨大，边界比虚机再薄一层，下一课展开。</p><p><span class="marginnote">常见误区：「有虚拟化就等于隔离了」。虚拟化只是把拦截交给硬件，隔离成立与否取决于设备模拟与管理接口这些特权侧代码有没有洞；IOMMU 挡得住设备 DMA 越界，但直通网卡自己的固件有洞照样穿透——机制要逐层验，不能按标签信。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零 PoC；边界要点名：硬件辅助只收缩通道不证明正确性——IOMMU 挡住设备 DMA 越界，但直通网卡自身固件有洞照样穿透。容器逃逸下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>侧信道漏 C；逃逸破隔离完整。</li><li>设备模拟是高危 TCB。</li><li>虚拟化不是自动证明。</li><li>下一课容器逃逸。</li><li>出处：Barham et al., Xen, 2003；Anderson。</li></ul>',7))])}const C=B(p,[["render",d]]);export{u as __pageData,C as default};
